1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Pulsing Circle</title>
7	  <style>
8	    :root {
9	      --circle-hue: #8ec5ff;
10	      --circle-core: #4a7dd9;
11	      --circle-shadow: #1f3a75;
12	      --cycle: 2.5s;
13	    }
14	    * {
15	      margin: 0;
16	      padding: 0;
17	      box-sizing: border-box;
18	    }
19	    body {
20	      width: 100vw;
21	      height: 100vh;
22	      display: flex;
23	      justify-content: center;
24	      align-items: center;
25	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
26	      overflow: hidden;
27	    }
28	    svg {
29	      width: min(400px, 80vmin);
30	      height: min(400px, 80vmin);
31	      overflow: visible;
32	      cursor: pointer;
33	      transition: filter 0.3s ease;
34	    }
35	    svg:hover {
36	      filter: brightness(1.08);
37	    }
38	    svg:focus-visible {
39	      outline: 2px solid var(--circle-hue);
40	      outline-offset: 8px;
41	      border-radius: 50%;
42	    }
43	    .ambient {
44	      fill: var(--circle-hue);
45	      opacity: 0.12;
46	      filter: blur(30px);
47	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
48	      transform-origin: 200px 200px;
49	      will-change: transform, opacity;
50	    }
51	    .core {
52	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
53	      transform-origin: 200px 200px;
54	      filter: url(#glow);
55	      will-change: transform, opacity;
56	    }
57	    .highlight {
58	      fill: url(#highlightGradient);
59	      transform-origin: 200px 200px;
60	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
61	      pointer-events: none;
62	      will-change: transform, opacity;
63	    }
64	    .ring {
65	      fill: none;
66	      stroke: var(--circle-hue);
67	      stroke-width: 2.5;
68	      transform-origin: 200px 200px;
69	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
70	      will-change: transform, opacity, stroke-width;
71	    }
72	    .ring--delay-1 {
73	      animation-delay: calc(var(--cycle) / 3);
74	    }
75	    .ring--delay-2 {
76	      animation-delay: calc(var(--cycle) / 3 * 2);
77	    }
78	    @keyframes pulse {
79	      0%, 100% {
80	        transform: scale(1);
81	        opacity: 0.9;
82	      }
83	      50% {
84	        transform: scale(1.05);
85	        opacity: 1;
86	      }
87	    }
88	    @keyframes breathe {
89	      0%, 100% {
90	        transform: scale(0.95);
91	        opacity: 0.1;
92	      }
93	      50% {
94	        transform: scale(1.1);
95	        opacity: 0.18;
96	      }
97	    }
98	    @keyframes ripple {
99	      0% {
100	        transform: scale(1);
101	        opacity: 0.6;
102	        stroke-width: 2.5;
103	      }
104	      100% {
105	        transform: scale(1.35);
106	        opacity: 0;
107	        stroke-width: 0.5;
108	      }
109	    }
110	    @media (prefers-reduced-motion: reduce) {
111	      .core, .ring, .ambient, .highlight {
112	        animation: none;
113	      }
114	      .ring {
115	        opacity: 0.35;
116	      }
117	      .ambient {
118	        opacity: 0.12;
119	      }
120	    }
121	    body.paused .core,
122	    body.paused .ring,
123	    body.paused .ambient,
124	    body.paused .highlight {
125	      animation-play-state: paused;
126	    }
127	    .speed-label {
128	      position: absolute;
129	      bottom: 24px;
130	      left: 50%;
131	      transform: translateX(-50%);
132	      color: var(--circle-hue);
133	      font-family: system-ui, sans-serif;
134	      font-size: 0.85rem;
135	      letter-spacing: 0.05em;
136	      opacity: 0.7;
137	      user-select: none;
138	    }
139	  </style>
140	</head>
141	<body>
142	  <svg id="ae683f770" viewBox="0 0 400 400" role="img" tabindex="0" aria-label="Pulsing blue circle animation. Click or press Enter to change pulse speed.">
143	    <defs>
144	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
145	        <stop offset="0%" stop-color="#8ec5ff"/>
146	        <stop offset="55%" stop-color="#4a7dd9"/>
147	        <stop offset="100%" stop-color="#1f3a75"/>
148	      </radialGradient>
149	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
150	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
151	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
152	      </radialGradient>
153	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
154	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
155	        <feColorMatrix in="blur" type="matrix"
156	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
157	        <feMerge>
158	          <feMergeNode in="tintedBlur"/>
159	          <feMergeNode in="SourceGraphic"/>
160	        </feMerge>
161	      </filter>
162	    </defs>
163	    <circle class="ambient" cx="200" cy="200" r="160"/>
164	    <circle class="ring" cx="200" cy="200" r="140"/>
165	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
166	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
167	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
168	    <circle class="highlight" cx="200" cy="200" r="140"/>
169	  </svg>
170	  <p class="speed-label" id="speedLabel" aria-live="polite">Normal speed</p>
171	  <script>
172	    const svg = document.getElementById('ae683f770');
173	    const speedLabel = document.getElementById('speedLabel');
174	    const speeds = [
175	      { value: '2.5s', name: 'Normal speed' },
176	      { value: '1.2s', name: 'Fast speed' },
177	      { value: '4.5s', name: 'Slow speed' },
178	    ];
179	    let speedIndex = 0;
180	
181	    function cycleSpeed() {
182	      speedIndex = (speedIndex + 1) % speeds.length;
183	      const { value, name } = speeds[speedIndex];
184	      svg.style.setProperty('--cycle', value);
185	      speedLabel.textContent = name;
186	      svg.setAttribute('aria-label', `Pulsing blue circle animation, ${name.toLowerCase()}. Click or press Enter to change pulse speed.`);
187	    }
188	
189	    svg.addEventListener('click', cycleSpeed);
190	    svg.addEventListener('keydown', (e) => {
191	      if (e.key === 'Enter' || e.key === ' ') {
192	        e.preventDefault();
193	        cycleSpeed();
194	      }
195	    });
196	
197	    document.addEventListener('visibilitychange', () => {
198	      document.body.classList.toggle('paused', document.hidden);
199	    });
200	  </script>
201	</body>
202	</html>
