let speedIndex = 0;

function cycleSpeed() {
  speedIndex = (speedIndex + 1) % speeds.length;
  const { value, name } = speeds[speedIndex];
  svg.style.setProperty('--cycle', value);
  speedLabel.textContent = name;
  svg.setAttribute('aria-label', `Pulsing blue circle animation, ${name.toLowerCase()}. Click or press Enter to change pulse speed.`);
}

svg.addEventListener('click', cycleSpeed);
svg.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
    cycleSpeed();
  }
});

document.addEventListener('visibilitychange', () => {
  document.body.classList.toggle('paused', document.hidden);
});

