let speedIndex = 0;
let manuallyPaused = false;

function updateAriaLabel() {
  const { name } = speeds[speedIndex];
  const state = manuallyPaused ? 'paused' : name.toLowerCase();
  svg.setAttribute('aria-label', `Pulsing blue circle animation, ${state}. Click or press Enter to change pulse speed. Press space to pause.`);
}

function cycleSpeed() {
  speedIndex = (speedIndex + 1) % speeds.length;
  const { value, name } = speeds[speedIndex];
  svg.style.setProperty('--cycle', value);
  speedLabel.firstChild.textContent = name + ' ';
  updateAriaLabel();
}

function togglePause() {
  manuallyPaused = !manuallyPaused;
  document.body.classList.toggle('paused', manuallyPaused);
  updateAriaLabel();
}

svg.addEventListener('click', cycleSpeed);
svg.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    cycleSpeed();
  } else if (e.key === ' ') {
    e.preventDefault();
    togglePause();
  }
});

document.addEventListener('visibilitychange', () => {
  document.body.classList.toggle('paused', document.hidden || manuallyPaused);
});

